// Human review status of the Hindi and Tamil UI strings (Decision 5,
// docs/translation-review.md). Set status to "approved" with the reviewer's
// name and date only after a fluent speaker has signed off.
export const TRANSLATION_REVIEW={hi:{status:"pending_review",method:"machine_draft",reviewer:null,reviewedAt:null},ta:{status:"pending_review",method:"machine_draft",reviewer:null,reviewedAt:null}};// Languages offered on the consent banner (English + Eighth Schedule
// languages, DPDP Act 2023 s.5(3), s.6(3)). Labels are in their own script.
export const CONSENT_LANGUAGES=[{code:"en",label:"English"},{code:"hi",label:"हिन्दी"},{code:"ta",label:"தமிழ்"}];export function isApproved(code){if(code==="en")return true;const review=TRANSLATION_REVIEW[code];return Boolean(review&&review.status==="approved"&&review.reviewer);}// Unreviewed languages are offered in development and test builds (marked as
// drafts) but hidden in production unless explicitly enabled.
export function isLanguageOffered(code){let env=arguments.length>1&&arguments[1]!==undefined?arguments[1]:process.env;if(isApproved(code))return true;return env.NODE_ENV!=="production"||env.REACT_APP_ENABLE_UNREVIEWED_LANGUAGES==="true";}export function offeredLanguages(){let env=arguments.length>0&&arguments[0]!==undefined?arguments[0]:process.env;return CONSENT_LANGUAGES.filter(l=>isLanguageOffered(l.code,env));}
